function approvalDecision(response,startedAt,timeoutHours,now) {
  if (Date.parse(now)>Date.parse(startedAt)+timeoutHours*3600000) return 'expired';
  const data=response?.data??response;
  if (!data||data.approved!==true) return data?.approved===false?'declined':'expired';
  return 'approved';
}

function clone(value) { return JSON.parse(JSON.stringify(value)); }

function contextFor(config,publication) {
  if (!publication.publicUrl) throw Error('The workspace needs a public URL before linking a registry');
  return stable([publication.publicUrl,config.spreadsheetId,config.sheetName,config.syncKey]);
