function readRows(input,config) {
  const rows=input.filter(r=>r&&Object.keys(r).some(k=>k!=='row_number'&&r[k]!==''&&r[k]!=null));
  if (rows.length>250) throw Error('More than 250 populated rows; split the source before synchronizing');
  const ids=new Set(),approved=[];let skipped=0;
