    const row=rows[index],id=String(row.id??'').trim();
    if (id) {if (ids.has(id)) throw Error('Duplicate source id: '+id);ids.add(id);}
    if (!flag(row.approved,'approved on row '+(index+2))) {skipped++;continue;}
    if (!/^[a-z0-9][a-z0-9_-]{0,39}$/.test(id)) throw Error('Approved rows need a stable lowercase id');
    const action=String(row.action||'UPSERT').trim().toUpperCase();
    if (!['UPSERT','DELETE'].includes(action)) throw Error('Unknown action for '+id);
