  const r=records[0];let snapshot;
  try {snapshot=JSON.parse(r.snapshot||'{"items":{},"section":null}');} catch {throw Error('Invalid registry snapshot');}
  if (!snapshot||!snapshot.items||typeof snapshot.items!=='object'||Array.isArray(snapshot.items)) throw Error('Invalid registry ownership data');
  return {...r,snapshot};
}

function makePlan(input) {
  const {config,rows,publication}=input;
  if (!input.menu||!Array.isArray(input.menu.items)||!Array.isArray(input.menu.sections)) throw Error('OrbitPage returned no native menu');
  const revision=Number(input.revision);
  if (!Number.isSafeInteger(revision)||revision<0||publication.draftRevision!==revision) throw Error('The settings and publication revisions differ');
  if (publication.draftRevision!==publication.publishedRevision) throw Error('Publish or reconcile unrelated private changes before synchronizing');
  if (input.menu.currency!==config.currency) throw Error('The configured currency differs from the menu; no automatic currency conversion');
  const context=contextFor(config,publication),registry=input.registry;
  if (registry&&registry.context!==context) throw Error('The registry belongs to another sheet, namespace or workspace');
  if (registry&&registry.state!=='idle') throw Error('A pending or uncertain execution is held for reconciliation');
  const parsed=readRows(rows,config),menu=clone(input.menu),snapshot=clone(registry?.snapshot||{section:null,items:{}});
  const sectionId='gs-'+config.syncKey+'-section';
  const existingSection=menu.sections.find(s=>s.id===sectionId);
  const upserts=parsed.rows.filter(r=>r.action==='UPSERT');
  const changes=[],warnings=[];
  if (upserts.length) {
    if (existingSection) {
      if (!snapshot.section) throw Error('Section ID collision: the registry does not own this section');
      if (stable({id:existingSection.id,name:existingSection.name})!==stable(snapshot.section)) throw Error('The managed section was edited in OrbitPage');
      if (existingSection.name!==config.sectionName) {changes.push({action:'section',id:sectionId,before:{name:existingSection.name},after:{name:config.sectionName}});existingSection.name=config.sectionName;}
    } else {
      if (snapshot.section) throw Error('The managed section was removed in OrbitPage');
      if (menu.sections.length>=30) throw Error('Native menu section limit reached');
      menu.sections.push({id:sectionId,name:config.sectionName,description:'',visible:true,position:menu.sections.length});
      changes.push({action:'section',id:sectionId,before:null,after:{name:config.sectionName}});
    }
    snapshot.section={id:sectionId,name:config.sectionName};
  }
  for (const row of parsed.rows) {
    const id='gs-'+config.syncKey+'-'+row.id;
    const at=menu.items.findIndex(item=>item.id===id),current=at<0?null:menu.items[at],previous=snapshot.items[id];
    if (current&&!previous) throw Error('Item ID collision: '+row.id+' is not owned by this registry');
    if (current&&stable(itemProjection(current))!==stable(previous)) throw Error('Managed fields were edited in OrbitPage: '+row.id);
    if (row.action==='DELETE') {
      if (current) {menu.items.splice(at,1);changes.push({action:'delete',id,before:itemProjection(current),after:null});}
      delete snapshot.items[id];continue;
    }
    if (!current&&previous) throw Error('A managed item was removed in OrbitPage: '+row.id);
    const desired={id,sectionId,name:row.name,description:row.description,priceMinor:row.priceMinor,available:row.available,position:row.position};
    if (!current) {
      menu.items.push({...desired,variants:[],allergens:[],dietaryTags:[],featured:false});
      changes.push({action:'add',id,before:null,after:desired});
    } else if (stable(itemProjection(current))!==stable(desired)) {
      menu.items[at]={...current,...desired};
      changes.push({action:'update',id,before:itemProjection(current),after:desired});
    }
    snapshot.items[id]=desired;
  }
  if (menu.items.length>250) throw Error('Native menu item limit reached');
  const missing=Object.keys(snapshot.items).filter(id=>!parsed.allIds.includes(id.slice(('gs-'+config.syncKey+'-').length)));
  if (missing.length) warnings.push(missing.length+' previously managed item(s) missing from the sheet were preserved; deletion requires an approved DELETE row.');
  if (!menu.enabled) warnings.push('Enable and configure the native menu in OrbitPage before applying this plan.');
  if (config.mode==='EMAIL_APPROVAL'&&changes.length&&!menu.enabled) throw Error('Enable and publish the native menu before using email-approved sync');
  return {config,context,revision:String(revision),originalPublishedRevision:publication.publishedRevision,baseMenu:clone(input.menu),menu,rows:clone(rows),sourceSignature:stable(rows),previousSnapshot:clone(registry?.snapshot||{section:null,items:{}}),nextSnapshot:snapshot,changes,warnings,hasChanges:changes.length>0,stateChanged:stable(snapshot)!==stable(registry?.snapshot||{section:null,items:{}}),stats:{added:changes.filter(c=>c.action==='add').length,updated:changes.filter(c=>c.action==='update').length,deleted:changes.filter(c=>c.action==='delete').length,skipped:parsed.skipped,missingPreserved:missing.length}};
}

const settings=$('Read current menu').first().json.body;
