function reviewEmail(plan) {
  const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const show=value=>value==null?'—':escape(value.name||value.id||'Section')+(value.description?'<br>'+escape(value.description):'')+(Number.isInteger(value.priceMinor)?'<br><strong>'+(value.priceMinor/100).toFixed(2)+' '+escape(plan.config.currency)+'</strong>':'')+(typeof value.available==='boolean'?'<br>'+(value.available?'Available':'Unavailable'):'')+(Number.isInteger(value.position)?'<br>Order: '+value.position:'');
  return '<h2>Review Google Sheets → OrbitPage</h2><p>Destination: '+escape(plan.config.publish?'PUBLIC PAGE':'PRIVATE DRAFT')+'. Approved rows only. Currency: '+escape(plan.config.currency)+'.</p><p>'+escape(JSON.stringify(plan.stats))+'</p><table border="1" cellpadding="8"><tr><th>Action / ID</th><th>Before</th><th>After</th></tr>'+plan.changes.map(c=>'<tr><td>'+escape(c.action+' '+c.id)+'</td><td>'+show(c.before)+'</td><td>'+show(c.after)+'</td></tr>').join('')+'</table><p>'+plan.warnings.map(escape).join('<br>')+'</p><p>Changes to the page or source sheet invalidate this review. Declining or timing out does not change the page.</p>';
}

