function approvalDecision(response,startedAt,timeoutHours,now) {
  if (Date.parse(now)>Date.parse(startedAt)+timeoutHours*3600000) return 'expired';
  const data=response?.data??response;
  if (!data||data.approved!==true) return data?.approved===false?'declined':'expired';
  return 'approved';
}

