function stable(value) {
  if (Array.isArray(value)) return '['+value.map(stable).join(',')+']';
  if (value && typeof value==='object') return '{'+Object.keys(value).sort().map(k=>JSON.stringify(k)+':'+stable(value[k])).join(',')+'}';
  return JSON.stringify(value);
}

function contextFor(config,publication) {
  if (!publication.publicUrl) throw Error('The workspace needs a public URL before linking a registry');
  return stable([publication.publicUrl,config.spreadsheetId,config.sheetName,config.syncKey]);
}

function decodeRegistry(rows) {
  const records=rows.filter(r=>r&&r.key);
  if (records.length>1) throw Error('Duplicate registry records: reconcile before continuing');
  if (!records.length) return null;
  const r=records[0];let snapshot;
  try {snapshot=JSON.parse(r.snapshot||'{"items":{},"section":null}');} catch {throw Error('Invalid registry snapshot');}
  if (!snapshot||!snapshot.items||typeof snapshot.items!=='object'||Array.isArray(snapshot.items)) throw Error('Invalid registry ownership data');
  return {...r,snapshot};
}

function recheckPlan(plan,current,executionId) {
  if (current.registry?.state!=='pending'||String(current.registry.execution_id)!==String(executionId)||current.registry.context!==plan.context) throw Error('This execution no longer owns the pending review');
  if (stable(current.registry.snapshot)!==stable(plan.previousSnapshot)) throw Error('The ownership snapshot changed during review');
  if (contextFor(plan.config,current.publication)!==plan.context) throw Error('Workspace identity changed');
  if (String(current.revision)!==plan.revision||current.publication.draftRevision!==Number(plan.revision)||current.publication.publishedRevision!==plan.originalPublishedRevision) throw Error('The workspace revision changed after review');
  if (stable(current.menu)!==stable(plan.baseMenu)) throw Error('The menu changed after review');
  if (stable(current.rows)!==plan.sourceSignature) throw Error('The sheet changed after review; generate a new diff');
  return plan;
}

