}

function verifyWrite(plan,response,settings,publication) {
  const revision=Number(response.revision);
  if (!Number.isSafeInteger(revision)||revision<=Number(plan.revision)||settings.revision!==revision||publication.draftRevision!==revision) throw Error('The resulting draft revision was not confirmed');
  const actual=clone(settings.data.menu),expected=clone(plan.menu);delete actual.updatedAt;delete expected.updatedAt;
  if (stable(actual)!==stable(expected)) throw Error('The saved menu differs from the reviewed menu');
  if (plan.config.publish) {
    if (publication.publishedRevision!==revision||publication.publicationStatus!=='published') throw Error('Publication was not confirmed');
  } else if (publication.publishedRevision!==plan.originalPublishedRevision) throw Error('The public revision changed while saving a private draft');
  return {revision,message:plan.config.publish?'Reviewed native menu published and verified.':'Reviewed native menu saved as a private draft and verified; publish it separately before another sync.'};
}

